#!/usr/bin/env python3
import pathlib,json,collections,csv
B=pathlib.Path(__file__).resolve().parents[1];P=B/'provenance';h=json.load(open(P/'history.json'))
def cat(p):
 if p.startswith('Computability/DiophantineConsistency/Lean/'):return 'active Lean'
 if p.startswith('docs/incoming/'):return 'incoming archive'
 if '/research/' in p:return 'research archive'
 if '/reviews/' in p:return 'review documentation'
 return 'project documentation'
rows=[]
for c in h['commits']:
 d=json.load(open(P/'commits'/(c['sha']+'.json')));gs=collections.Counter(cat(f['filename']) for f in d['files']);kind=('merge' if len(d['parents'])>1 else 'commit')
 rows.append({'sha':c['sha'],'utc':d['commit']['committer']['date'],'kind':kind,'message':d['commit']['message'].split('\n')[0],'file_classes':dict(gs),'files':[f['filename'] for f in d['files']]})
(P/'commit_timeline.json').write_text(json.dumps(rows,indent=2)+'\n')
out=['# Recent commit and snapshot audit','','Head: `b310142330df89e48413c8fce62e7de223e1c7d5` (2026-10-26 16:18:46 UTC).','Previous pin: `60e9c5d620c6c387d932876cfa2d9376f64ea56c`.','Compare: ahead by 21 commits, behind by 0; previous pin is the merge base.','','## What changed','','The net diff contains 29 active Lean files: **28 newly added modules** (14 proof/definition modules plus 14 Checks modules), and 14 added imports in the existing root module. No existing active proof body was changed in this interval. The active Lean change is +3307/-0 lines; +3293 lines are newly added modules.','','The other net changes are 60 research-archive files (+54237/-0), 29 review documents (+2285/-0), 2 project documents (+136/-11), and 6 incoming archive file changes. Archive additions are not active proof simplifications. Merge commit file lists are first-parent diffs and are therefore not summed to compute net counts.','','## Timeline','','| UTC | Commit | Kind | Files by category | Subject |','|---|---|---|---|---|']
for r in rows:
 out.append('| '+r['utc'][11:19]+' | [`'+r['sha'][:10]+'`](https://github.com/VladimirReshetnikov/ProveIt/commit/'+r['sha']+') | '+r['kind']+' | '+', '.join(f'{k}: {v}' for k,v in r['file_classes'].items())+' | '+r['message'].replace('|','\\|')+' |')
out+=['','## Snapshot scope and verification','','`sources/` contains 826 selected files, each independently checked using the Git object identity `SHA1("blob " ++ decimal_byte_length ++ NUL ++ bytes)` against the pinned Git trees, and recorded with SHA-256. All 826 checks pass. 766 unchanged files were reused only after comparing their computed object identity to the newly retrieved HEAD tree; 60 files were retrieved by immutable Git blob URL via the connected GitHub read-only tool.','','Included: all 574 `.lean` files in the active `Lean/` subtree, its toolchain/configuration files, root project configuration and license, target top-level Markdown, relevant generator scripts, and Lean review documents including all 29 newly changed review documents. The large historical research archive is deliberately not rematerialized; the net diff and source links identify it separately. Incoming ZIP contents are handled by the separate novelty audit.','','GitHub tree traversal: root -> Computability -> DiophantineConsistency; then explicit Lean/reviews/scripts/tools subtrees. The first recursive target-tree call returned a transient transport-closed error; smaller subtree GETs succeeded. No repository writes or toolchain installation were attempted.','','## Validation boundary','','This audit verifies source bytes, provenance, and textual changes, not Lean elaboration or kernel acceptance. Lean/Lake are not installed in this execution environment. Build-success statements in upstream review documents remain upstream claims, not independently reproduced runs.','','## Artifacts','','- `source_manifest.json`: path, pinned object SHA, SHA-256, retrieval method, source URL.','- `verification_result.json`: counts and failures (none).','- `history.json`: complete pinned compare including file patches.','- `commits/`: metadata and compact per-commit file listings.','- `commit_timeline.json`: machine-readable timeline and categories.','- `changed_files_classified.json`: net-diff file classes.','- `root_tree.json`, `computability_tree.json`, `target_root_tree.json`, subtree files: fresh Git tree evidence.']
(P/'RECENT_COMMITS.md').write_text('\n'.join(out)+'\n');print('\n'.join(out[:14]))
